# Instead of cryptic timing, use @shortcuts:
@reboot  /home/alice/startup.sh         # run once at system boot
@hourly  /home/alice/check.sh           # = 0 * * * *
@daily   /home/alice/backup.sh          # = 0 0 * * *  (midnight)
@weekly  /home/alice/cleanup.sh         # = 0 0 * * 0  (Sunday midnight)
@monthly /home/alice/report.sh          # = 0 0 1 * *
@yearly  /home/alice/annual.sh          # = 0 0 1 1 *

# @reboot is especially useful for starting services
# after a reboot without systemd
